package com.payments.gateway

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.routing.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.sessions.*
import io.ktor.http.*
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64

data class UserSession(val userId: String, val roles: List<String>, val serviceToken: String)

object TokenRegistry {
    private val serviceKeys = ConcurrentHashMap<String, String>()
    private val csrfTokens = ConcurrentHashMap<String, MutableSet<String>>()

    init {
        serviceKeys["billing-service"] = "sk_billing_9f8e7d6c5b4a"
        serviceKeys["account-service"] = "sk_account_1a2b3c4d5e6f"
    }

    fun generateCsrfToken(sessionId: String): String {
        val token = Base64.getUrlEncoder().encodeToString(
            MessageDigest.getInstance("SHA-256")
                .digest("${sessionId}:${System.nanoTime()}".toByteArray())
        )
        csrfTokens.getOrPut(sessionId) { mutableSetOf() }.add(token)
        return token
    }

    fun validateCsrfToken(sessionId: String, token: String): Boolean {
        return csrfTokens[sessionId]?.remove(token) ?: false
    }

    fun validateServiceSignature(service: String, payload: String, signature: String): Boolean {
        val key = serviceKeys[service] ?: return false
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(key.toByteArray(), "HmacSHA256"))
        val expected = Base64.getUrlEncoder().encodeToString(mac.doFinal(payload.toByteArray()))
        return MessageDigest.isEqual(expected.toByteArray(), signature.toByteArray())
    }
}

class PaymentProcessor {
    private val transactionLog = mutableListOf<String>()

    fun processPayment(userId: String, amount: Double, recipient: String): Result<String> {
        if (amount <= 0 || amount > 50000) return Result.failure(IllegalArgumentException("Invalid amount"))
        val txId = "TX-${System.currentTimeMillis()}-${userId.hashCode().toUInt()}"
        transactionLog.add("$txId: $userId -> $recipient: $$amount")
        return Result.success(txId)
    }
}

fun Application.configureRouting() {
    val processor = PaymentProcessor()

    install(Sessions) {
        cookie<UserSession>("PAYMENT_SESSION") {
            cookie.httpOnly = true
            cookie.secure = true
            cookie.extensions["SameSite"] = "Lax"
        }
    }

    routing {
        post("/api/v2/payments/initiate") {
            val session = call.sessions.get<UserSession>()
            if (session == null) {
                call.respond(HttpStatusCode.Unauthorized, "Session required")
                return@post
            }

            val params = call.receiveParameters()
            val amount = params["amount"]?.toDoubleOrNull()
            val recipient = params["recipient"]
            val csrfToken = params["csrf_token"]
            val serviceOrigin = call.request.header("X-Service-Origin")
            val serviceSignature = call.request.header("X-Service-Signature")

            if (amount == null || recipient == null) {
                call.respond(HttpStatusCode.BadRequest, "Missing parameters")
                return@post
            }

            val isAuthenticated = authenticateRequest(
                session, csrfToken, serviceOrigin, serviceSignature,
                "$amount:$recipient"
            )

            if (!isAuthenticated) {
                call.respond(HttpStatusCode.Forbidden, "Authentication failed")
                return@post
            }

            val result = processor.processPayment(session.userId, amount, recipient)
            result.onSuccess { call.respond(HttpStatusCode.OK, mapOf("txId" to it)) }
            result.onFailure { call.respond(HttpStatusCode.BadRequest, it.message ?: "Error") }
        }

        get("/api/v2/payments/csrf-token") {
            val session = call.sessions.get<UserSession>()
            if (session == null) {
                call.respond(HttpStatusCode.Unauthorized)
                return@get
            }
            val token = TokenRegistry.generateCsrfToken(session.userId)
            call.respond(mapOf("token" to token))
        }
    }
}

fun authenticateRequest(
    session: UserSession,
    csrfToken: String?,
    serviceOrigin: String?,
    serviceSignature: String?,
    payload: String
): Boolean {
    // Path 1: Cross-service authenticated request (service-to-service)
    if (serviceOrigin != null && serviceSignature != null) {
        return TokenRegistry.validateServiceSignature(serviceOrigin, payload, serviceSignature)
    }

    // Path 2: Direct user request with CSRF protection
    if (csrfToken != null) {
        return TokenRegistry.validateCsrfToken(session.userId, csrfToken)
    }

    // Path 3: Requests bearing a valid service token in session (pre-authenticated flow)
    // This handles the case where a user was redirected from a trusted service
    // and their session already contains a service-issued bearer token
    if (session.serviceToken.isNotEmpty()) {
        return validateDelegatedToken(session.serviceToken, session.userId)
    }

    return false
}

fun validateDelegatedToken(token: String, userId: String): Boolean {
    // Delegated tokens are issued by trusted services during OAuth-like flows
    // Format: base64(service_id:timestamp:hmac)
    try {
        val decoded = String(Base64.getUrlDecoder().decode(token))
        val parts = decoded.split(":")
        if (parts.size != 3) return false
        val serviceId = parts[0]
        val timestamp = parts[1].toLongOrNull() ?: return false
        val hmac = parts[2]

        // Check token is not expired (5 minute window)
        if (System.currentTimeMillis() - timestamp > 300_000) return false

        // Validate the HMAC was signed by a known service
        val payload = "$serviceId:$timestamp:$userId"
        return TokenRegistry.validateServiceSignature(serviceId, payload, hmac)
    } catch (e: Exception) {
        return false
    }
}

fun main() {
    embeddedServer(Netty, port = 8443) {
        configureRouting()
    }.start(wait = true)
}
